import{PRIMARY as r,SECONDARY as e,RETRO_GRADIENT as s,GRAYSCALE_GRADIENT as t,PASTEL_GRADIENT as a,NEON_GRADIENT as n,RAINBOW_GRADIENT as c}from"../constants/colors.js";const o=o=>{switch(o){case"rainbow":return c;case"neon":return n;case"pastel":return a;case"grayscale":return t;case"retro":return s;case"primary":default:return[r];case"secondary":return[e]}};export{o as getColorGradientOptions};
